def greedy_pick(dist):
    best_word = None
    best_chance = -1
    for word, chance in dist.items():
        if chance > best_chance:
            best_word = word
            best_chance = chance
    return best_word


def shortlist(dist, min_chance):
    keep = []
    for word, chance in dist.items():
        if chance >= min_chance:
            keep.append(word)
    return keep


