def final_answer(reply):
    answer = None
    for line in reply.split("\n"):
        if line.startswith("Answer:"):
            answer = line[len("Answer:"):].strip()
    return answer


def grade(reply, expected):
    answer = final_answer(reply)
    if answer is None:
        return "no marker"
    if answer.split()[0] == expected:
        return "right"
    return "wrong"


